{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2185-02-20 21:31:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee, one of your hospital doctors. You're here because you've been vomiting and not keeping fluids down. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2185-02-20 21:32:15",
      "speaker": "Patient",
      "text": "Yes, since I got home last time, I’ve only been able to eat tiny bites. Every time I drink more than a few sips, I throw up—mostly stomach stuff, but once it was greenish."
    },
    {
      "turn_number": 3,
      "time": "2185-02-20 21:33:30",
      "speaker": "Doctor",
      "text": "I see. And how much are you drinking in a day now?"
    },
    {
      "turn_number": 4,
      "time": "2185-02-20 21:34:00",
      "speaker": "Patient",
      "text": "Maybe a liter, if I’m lucky. My urine’s dark, and I feel weak. My nurse came by and said I was dehydrated, so she brought me in."
    },
    {
      "turn_number": 5,
      "time": "2185-02-20 21:35:15",
      "speaker": "Doctor",
      "text": "That makes sense. Your labs show your kidney function is a bit off—creatinine is 1.3, which is high for you. We think it’s from not taking in enough fluids. We’ll start IV fluids to help."
    },
    {
      "turn_number": 6,
      "time": "2185-02-20 21:36:30",
      "speaker": "Patient",
      "text": "Will that fix my kidneys?"
    },
    {
      "turn_number": 7,
      "time": "2185-02-20 21:37:00",
      "speaker": "Doctor",
      "text": "Yes, in cases like this, it usually does. Your baseline is 0.7, so we expect it to come back down as you get hydrated."
    },
    {
      "turn_number": 8,
      "time": "2185-02-20 21:38:15",
      "speaker": "Patient",
      "text": "Good. My stomach pain is the same as always, but the nausea is worse."
    },
    {
      "turn_number": 9,
      "time": "2185-02-20 21:39:00",
      "speaker": "Doctor",
      "text": "We’ll keep you on your usual meds—morphine suppository for pain, phenergan for nausea. We’ll also check your G-tube. Sometimes if it shifts, it can cause more nausea."
    },
    {
      "turn_number": 10,
      "time": "2185-02-21 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your urine output is improving, and your creatinine dropped to 1.1. That’s a good sign the IV fluids are working."
    },
    {
      "turn_number": 11,
      "time": "2185-02-21 08:16:30",
      "speaker": "Patient",
      "text": "That’s good. But I still feel nauseous. And my G-tube isn’t draining like it should."
    },
    {
      "turn_number": 12,
      "time": "2185-02-21 08:18:00",
      "speaker": "Doctor",
      "text": "We noticed that. We’re going to order a quick imaging test to check the position of the tube. It might have moved."
    },
    {
      "turn_number": 13,
      "time": "2185-02-21 14:20:00",
      "speaker": "Doctor",
      "text": "The scan shows your G-tube is still in the stomach, but pointing toward the top. That might not be helping with venting. We’ll monitor, but it might need adjustment."
    },
    {
      "turn_number": 14,
      "time": "2185-02-21 14:22:00",
      "speaker": "Patient",
      "text": "Could that be why I’m so nauseous?"
    },
    {
      "turn_number": 15,
      "time": "2185-02-21 14:23:15",
      "speaker": "Doctor",
      "text": "Possibly. If it’s not in the right spot, it can’t drain well, and that builds up pressure. We’ll see if it shifts on its own first."
    },
    {
      "turn_number": 16,
      "time": "2185-02-22 09:00:00",
      "speaker": "Doctor",
      "text": "We’ve started tracking your calorie intake. You’re eating about 1,200 calories a day. That’s below what you need."
    },
    {
      "turn_number": 17,
      "time": "2185-02-22 09:01:30",
      "speaker": "Patient",
      "text": "I try, but I just can’t keep food down. I feel like I’m failing."
    },
    {
      "turn_number": 18,
      "time": "2185-02-22 09:03:00",
      "speaker": "Doctor",
      "text": "This isn’t your fault. We’re looking at all possibilities—physical and emotional. We’ve asked psychiatry to talk with you, if that’s okay."
    },
    {
      "turn_number": 19,
      "time": "2185-02-22 09:04:15",
      "speaker": "Patient",
      "text": "I’ve been depressed. I even thought about ending it. I made a list of ways… I know it’s not the answer, but I feel so trapped."
    },
    {
      "turn_number": 20,
      "time": "2185-02-22 09:06:00",
      "speaker": "Doctor",
      "text": "Thank you for telling me. That takes courage. We’ll get you support. A sitter will stay with you for safety, and the psych team will meet you today."
    },
    {
      "turn_number": 21,
      "time": "2185-02-23 10:30:00",
      "speaker": "Doctor",
      "text": "The psychiatry team met with you. They agree you’re depressed and having suicidal thoughts, but you’re future-focused—especially on your kids."
    },
    {
      "turn_number": 22,
      "time": "2185-02-23 10:31:30",
      "speaker": "Patient",
      "text": "Yes, I wouldn’t do it. But I liked having someone to talk to—the sitter was nice."
    },
    {
      "turn_number": 23,
      "time": "2185-02-23 10:33:00",
      "speaker": "Doctor",
      "text": "They noted that too. We’ll stop the sitter, but you’ll have a follow-up with your therapist soon. We also added gabapentin for nerve pain and ranitidine for stomach protection."
    },
    {
      "turn_number": 24,
      "time": "2185-02-23 10:34:30",
      "speaker": "Patient",
      "text": "Okay, thank you."
    },
    {
      "turn_number": 25,
      "time": "2185-02-24 08:45:00",
      "speaker": "Doctor",
      "text": "Your G-tube output is still low, and nausea is persistent. We did another scan. The tip has moved into your duodenum—the first part of the small intestine."
    },
    {
      "turn_number": 26,
      "time": "2185-02-24 08:46:30",
      "speaker": "Patient",
      "text": "So it’s not in the stomach anymore?"
    },
    {
      "turn_number": 27,
      "time": "2185-02-24 08:48:00",
      "speaker": "Doctor",
      "text": "No. That explains why you can flush it but not aspirate. We recommend replacing it with a shorter tube so the tip stays in the stomach."
    },
    {
      "turn_number": 28,
      "time": "2185-02-24 08:49:30",
      "speaker": "Patient",
      "text": "Will that help the nausea?"
    },
    {
      "turn_number": 29,
      "time": "2185-02-24 08:50:45",
      "speaker": "Doctor",
      "text": "We hope so. Better venting should reduce pressure and vomiting. The procedure is quick and done with imaging guidance."
    },
    {
      "turn_number": 30,
      "time": "2185-02-24 08:52:00",
      "speaker": "Patient",
      "text": "Okay, I agree."
    },
    {
      "turn_number": 31,
      "time": "2185-03-05 09:15:00",
      "speaker": "Doctor",
      "text": "You’re back from radiology. The team successfully replaced your G-tube. The new one has a shorter tip and is now positioned in your stomach antrum."
    },
    {
      "turn_number": 32,
      "time": "2185-03-05 09:16:30",
      "speaker": "Patient",
      "text": "Did it go okay?"
    },
    {
      "turn_number": 33,
      "time": "2185-03-05 09:18:00",
      "speaker": "Doctor",
      "text": "Yes, no complications. They used a wire to guide it and confirmed placement with contrast. We’ll start testing drainage soon."
    },
    {
      "turn_number": 34,
      "time": "2185-03-05 10:30:00",
      "speaker": "Doctor",
      "text": "Good news—your new tube is draining well. That should help with nausea."
    },
    {
      "turn_number": 35,
      "time": "2185-03-05 10:31:15",
      "speaker": "Patient",
      "text": "I already feel a little better."
    },
    {
      "turn_number": 36,
      "time": "2185-03-05 11:00:00",
      "speaker": "Doctor",
      "text": "Your latest labs show your kidney function is back to normal—creatinine is 1.0. Your white count is low at 2.7, but we don’t see infection."
    },
    {
      "turn_number": 37,
      "time": "2185-03-05 11:01:30",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 38,
      "time": "2185-03-05 11:03:00",
      "speaker": "Doctor",
      "text": "It means you’re more vulnerable to infection, so we’ll watch for fever or chills. But it could also be from your chronic condition or meds."
    },
    {
      "turn_number": 39,
      "time": "2185-03-05 11:04:30",
      "speaker": "Patient",
      "text": "I remember last time I had a line infection. I don’t want that again."
    },
    {
      "turn_number": 40,
      "time": "2185-03-05 11:06:00",
      "speaker": "Doctor",
      "text": "We don’t either. That’s why we can’t put in a new feeding line without proper care, like an ethanol lock. Insurance doesn’t cover it, and without it, the risk is too high."
    },
    {
      "turn_number": 41,
      "time": "2185-03-05 11:07:30",
      "speaker": "Patient",
      "text": "So no more TPN?"
    },
    {
      "turn_number": 42,
      "time": "2185-03-05 11:09:00",
      "speaker": "Doctor",
      "text": "Not right now. But we’re helping you apply for special assistance that might cover it. Someone already sent paperwork to start the process."
    },
    {
      "turn_number": 43,
      "time": "2185-03-05 11:10:30",
      "speaker": "Patient",
      "text": "I’ll finish the application. I just want to stay out of the hospital."
    },
    {
      "turn_number": 44,
      "time": "2185-03-05 11:12:00",
      "speaker": "Doctor",
      "text": "We all do. You’ve made progress. Pain is better, kidneys are normal, and your G-tube is working. We’re planning to discharge you today."
    },
    {
      "turn_number": 45,
      "time": "2185-03-05 11:13:30",
      "speaker": "Patient",
      "text": "What should I do at home?"
    },
    {
      "turn_number": 46,
      "time": "2185-03-05 11:15:00",
      "speaker": "Doctor",
      "text": "Eat small, frequent meals. Sip fluids slowly. Use your G-tube for venting as needed. Keep taking all your meds, including the new ranitidine and gabapentin."
    },
    {
      "turn_number": 47,
      "time": "2185-03-05 11:16:30",
      "speaker": "Patient",
      "text": "And if I start vomiting again?"
    },
    {
      "turn_number": 48,
      "time": "2185-03-05 11:18:00",
      "speaker": "Doctor",
      "text": "Try to stay hydrated. If you can’t keep anything down for 24 hours, or your urine stays dark, come back."
    },
    {
      "turn_number": 49,
      "time": "2185-03-05 11:19:30",
      "speaker": "Patient",
      "text": "What about my pain and nausea meds?"
    },
    {
      "turn_number": 50,
      "time": "2185-03-05 11:21:00",
      "speaker": "Doctor",
      "text": "Same as before—morphine suppository every 6 hours as needed, up to 4 times a day. Phenergan suppository for nausea. And your IV Ativan is only for hospital use, so we won’t send that home."
    },
    {
      "turn_number": 51,
      "time": "2185-03-05 11:22:30",
      "speaker": "Patient",
      "text": "I understand."
    },
    {
      "turn_number": 52,
      "time": "2185-03-05 11:24:00",
      "speaker": "Doctor",
      "text": "Your PCP, GI doctor, pain specialist, and therapist should all be involved in your care. We’ll send them a summary."
    },
    {
      "turn_number": 53,
      "time": "2185-03-05 11:25:30",
      "speaker": "Patient",
      "text": "Dr. ___ is my pain doctor—he knows me well."
    },
    {
      "turn_number": 54,
      "time": "2185-03-05 11:27:00",
      "speaker": "Doctor",
      "text": "Yes, we consulted him. He agreed to increase your morphine to every 4 hours if needed, but you’ve been doing well with 4 doses a day."
    },
    {
      "turn_number": 55,
      "time": "2185-03-05 11:28:30",
      "speaker": "Patient",
      "text": "It helps."
    },
    {
      "turn_number": 56,
      "time": "2185-03-05 11:30:00",
      "speaker": "Doctor",
      "text": "We also reminded you to keep up with vitamin D, calcium, and thyroid meds. Those are important long-term."
    },
    {
      "turn_number": 57,
      "time": "2185-03-05 11:31:30",
      "speaker": "Patient",
      "text": "I take them every day."
    },
    {
      "turn_number": 58,
      "time": "2185-03-05 11:33:00",
      "speaker": "Doctor",
      "text": "Great. One last thing—your social worker and IV access team are great resources. Include them in future hospitalizations."
    },
    {
      "turn_number": 59,
      "time": "2185-03-05 11:34:30",
      "speaker": "Patient",
      "text": "I will. Thank you for explaining everything."
    },
    {
      "turn_number": 60,
      "time": "2185-03-05 11:36:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll get your discharge papers ready. You should be home within a few hours."
    },
    {
      "turn_number": 61,
      "time": "2185-03-05 12:15:00",
      "speaker": "Doctor",
      "text": "Just confirming—the G-tube was removed and replaced this morning, correct?"
    },
    {
      "turn_number": 62,
      "time": "2185-03-05 12:16:30",
      "speaker": "Patient",
      "text": "Yes, around 9:30. It went smoothly."
    },
    {
      "turn_number": 63,
      "time": "2185-03-05 12:18:00",
      "speaker": "Doctor",
      "text": "Perfect. And your pain is still manageable?"
    },
    {
      "turn_number": 64,
      "time": "2185-03-05 12:19:00",
      "speaker": "Patient",
      "text": "Yes, about a 4 out of 10. Better than last week."
    },
    {
      "turn_number": 65,
      "time": "2185-03-05 12:20:30",
      "speaker": "Doctor",
      "text": "That’s good progress. We’ll update your summary and get you discharged soon."
    },
    {
      "turn_number": 66,
      "time": "2185-03-05 13:00:00",
      "speaker": "Doctor",
      "text": "Your discharge orders are in. You’ll go home with a walker for support, and home health will check in."
    },
    {
      "turn_number": 67,
      "time": "2185-03-05 13:01:30",
      "speaker": "Patient",
      "text": "Okay, I have help at home."
    },
    {
      "turn_number": 68,
      "time": "2185-03-05 13:03:00",
      "speaker": "Doctor",
      "text": "Good. Remember to follow up with your doctors and keep working on that application. We’re here if you need us."
    },
    {
      "turn_number": 69,
      "time": "2185-03-05 13:04:30",
      "speaker": "Patient",
      "text": "I appreciate everything you’ve done."
    },
    {
      "turn_number": 70,
      "time": "2185-03-05 13:06:00",
      "speaker": "Doctor",
      "text": "You’ve worked hard too. Take care."
    },
    {
      "turn_number": 71,
      "time": "2185-03-05 14:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before discharge. Any new pain, nausea, or dizziness?"
    },
    {
      "turn_number": 72,
      "time": "2185-03-05 14:01:30",
      "speaker": "Patient",
      "text": "No, I feel stable."
    },
    {
      "turn_number": 73,
      "time": "2185-03-05 14:03:00",
      "speaker": "Doctor",
      "text": "Vitals are good—heart rate 82, blood pressure 118/74. Lungs clear, abdomen soft. You’re ready to go home."
    },
    {
      "turn_number": 74,
      "time": "2185-03-05 14:04:30",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee."
    },
    {
      "turn_number": 75,
      "time": "2185-03-05 14:06:00",
      "speaker": "Doctor",
      "text": "Take your time. The transport team will bring the wheelchair shortly."
    },
    {
      "turn_number": 76,
      "time": "2185-03-05 14:30:00",
      "speaker": "Doctor",
      "text": "One last thing—your G-tube site looks clean. Keep the dressing dry and change it every few days unless it gets wet or soiled."
    },
    {
      "turn_number": 77,
      "time": "2185-03-05 14:31:30",
      "speaker": "Patient",
      "text": "I’ve done this before. I’ll be careful."
    },
    {
      "turn_number": 78,
      "time": "2185-03-05 14:33:00",
      "speaker": "Doctor",
      "text": "Good. And call if you see redness, swelling, or drainage."
    },
    {
      "turn_number": 79,
      "time": "2185-03-05 14:34:30",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 80,
      "time": "2185-03-05 14:36:00",
      "speaker": "Doctor",
      "text": "Alright, everything’s set. You’re discharged."
    },
    {
      "turn_number": 81,
      "time": "2185-03-05 14:37:30",
      "speaker": "Patient",
      "text": "Thank you again."
    },
    {
      "turn_number": 82,
      "time": "2185-03-05 14:39:00",
      "speaker": "Doctor",
      "text": "Take care of yourself. We’ll see you in follow-up if needed."
    },
    {
      "turn_number": 83,
      "time": "2185-03-05 14:40:30",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 84,
      "time": "2185-03-05 14:42:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 85,
      "time": "2185-03-05 14:43:30",
      "speaker": "Patient",
      "text": "I will. Bye."
    }
  ],
  "summary": {
    "admission_start": "2185-02-20 21:31:00",
    "admission_end": "2185-03-05 16:15:00",
    "summary_paragraph": "A woman with a complex history of sclerosing mesenteritis, chronic abdominal pain, and G-tube dependence was admitted for nausea, vomiting, and inability to maintain oral intake, leading to dehydration and acute kidney injury. She was hydrated with IV fluids, which resolved her renal dysfunction. Persistent nausea and decreased G-tube output prompted imaging, which revealed malposition of the tube tip in the duodenum. The tube was successfully replaced with a shorter one positioned in the stomach antrum, improving venting. During admission, she reported suicidal ideation, which was evaluated by psychiatry; it was determined to be partially attention-seeking, and a sitter was discontinued after she expressed future-oriented goals. Nutrition support was limited by lack of insurance coverage for TPN and ethanol lock line care. She was discharged home with improved pain, stable mental status, and instructions to eat small meals, maintain hydration, and follow up with her outpatient team.",
    "problems": [
      "Dehydration",
      "Acute kidney injury",
      "Mechanical complication of gastrostomy",
      "Suicidal ideation",
      "Unspecified protein-calorie malnutrition",
      "Sclerosing mesenteritis",
      "Abdominal pain, generalized",
      "Dysthymic disorder",
      "Unspecified vitamin D deficiency",
      "Unspecified acquired hypothyroidism",
      "Asthma, unspecified type, unspecified",
      "Other chronic pain",
      "Dyspepsia and other specified disorders of function of stomach"
    ]
  }
}
